package org.firstinspires.ftc.teamcode.tuning;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

// Generated by refract-suite ftc-construct. Programs 8 / 9: picks the feed (intake power while firing) for a spot from
// the flywheel's speed dips, no hardware in here (ShotTuner fires, this decides).
// The dip's depth is mostly the energy the element took (wheel speed and element), so it says little about the feed.
// The spread (standard deviation) of the dips over several shots says how repeatable the exit speed is: steady dips = steady shots. Two dips
// in one feed = two elements went together. So: each candidate feed SHOTS_EACH shots; any double dip rules a feed out;
// the feed with the smallest spread wins only if it is CLEARLY steadier than the feed in use (by more than the speed
// reading's resolution and by CLEAR of its spread), else the feed in use stays: the hub reads speed in steps, and a
// difference smaller than a step is noise (in the sim, ties made it pick the fastest feed every time). Among clear
// winners within TIE of the best, the faster one (shorter cycle); then one feed half way toward the better neighbour.
public final class FeedCheck {
    public static final double[] CANDIDATES = {0.5, 0.35, 0.65, 0.8};
    public static final int SHOTS_EACH = 3;
    static final double TIE = 0.10, CLEAR = 0.25, RESOLUTIONS = 2;

    private final List<Double> feeds = new ArrayList<>();
    private final List<List<Double>> dips = new ArrayList<>();
    private final List<Boolean> doubled = new ArrayList<>();
    private int current = 0;
    private boolean refined = false, done = false;
    private final double inUse, resolution;

    // inUse: the feed the spot uses now (kept unless a candidate is clearly steadier); resolution: the smallest dip
    // difference the speed reading can show, as a share of the speed
    public FeedCheck(double inUse, double resolution) {
        this.inUse = inUse;
        this.resolution = resolution;
        for (double f : CANDIDATES) add(f);
    }

    private void add(double feed) {
        feeds.add(feed);
        dips.add(new ArrayList<>());
        doubled.add(false);
    }

    // the feed for the next shot
    public double feed() {
        return feeds.get(current);
    }

    public boolean done() {
        return done;
    }

    public int shotsTaken() {
        int n = 0;
        for (List<Double> l : dips) n += l.size();
        return n;
    }

    // shots this check takes (the refine adds SHOTS_EACH once it is known)
    public int shotsPlanned() {
        return feeds.size() * SHOTS_EACH;
    }

    // one shot at feed(): its dip as a share of the speed before it, and whether a second dip followed
    public void shot(double dipShare, boolean doubleDip) {
        if (done) return;
        dips.get(current).add(dipShare);
        if (doubleDip) doubled.set(current, true);
        if (dips.get(current).size() < SHOTS_EACH) return;
        current++;
        if (current < feeds.size()) return;
        if (!refined) {
            refined = true;
            double mid = refineFeed();
            if (!Double.isNaN(mid)) {
                add(mid);
                return;
            }
        }
        done = true;
    }

    // the feed to use: a clearly steadier one, else the feed in use
    public double chosen() {
        int best = pick();
        return best < 0 ? inUse : feeds.get(best);
    }

    // the candidate nearest the feed in use (its spread is what a winner must beat)
    private int reference() {
        int r = 0;
        for (int i = 1; i < feeds.size(); i++) if (Math.abs(feeds.get(i) - inUse) < Math.abs(feeds.get(r) - inUse)) r = i;
        return r;
    }

    // a feed's score: the spread of its dips (standard deviation: with 3 shots it uses all three, a median-based spread
    // picked the steadiest feed less often in the rule cases); a double dip rules it out
    double score(int i) {
        List<Double> l = dips.get(i);
        if (doubled.get(i) || l.size() < SHOTS_EACH) return Double.POSITIVE_INFINITY;
        double mean = 0, ss = 0;
        for (double v : l) mean += v;
        mean /= l.size();
        for (double v : l) ss += (v - mean) * (v - mean);
        return Math.sqrt(ss / (l.size() - 1));
    }

    // a clearly steadier feed (index), or -1 = keep the feed in use
    private int pick() {
        double best = Double.POSITIVE_INFINITY;
        for (int i = 0; i < feeds.size(); i++) best = Math.min(best, score(i));
        if (Double.isInfinite(best)) {
            // every feed doubled (or none finished): the gentlest feed that finished
            int out = -1;
            for (int i = 0; i < feeds.size(); i++) if (dips.get(i).size() >= SHOTS_EACH && (out < 0 || feeds.get(i) < feeds.get(out))) out = i;
            return out;
        }
        double ref = score(reference());
        // 3 readings in steps of `resolution` easily come out all equal (spread 0) or one step apart (spread ~1.2 steps)
        // by luck: a winner has to beat the feed in use by more than RESOLUTIONS steps
        if (!Double.isInfinite(ref) && ref - best <= Math.max(RESOLUTIONS * resolution, CLEAR * ref)) return -1;
        int out = -1;
        for (int i = 0; i < feeds.size(); i++) {
            if (score(i) <= best * (1 + TIE) + 1e-12 && (out < 0 || feeds.get(i) > feeds.get(out))) out = i;
        }
        return out;
    }

    // half way from the best feed toward its better-scoring neighbour (by feed), NaN if there is none
    private double refineFeed() {
        int best = pick();
        if (best < 0 || best == reference()) return Double.NaN;
        double b = feeds.get(best), lower = Double.NaN, upper = Double.NaN;
        int lo = -1, hi = -1;
        for (int i = 0; i < feeds.size(); i++) {
            double f = feeds.get(i);
            if (f < b && (lo < 0 || f > feeds.get(lo))) lo = i;
            if (f > b && (hi < 0 || f < feeds.get(hi))) hi = i;
        }
        if (lo >= 0) lower = score(lo);
        if (hi >= 0) upper = score(hi);
        int toward = lo >= 0 && (hi < 0 || lower <= upper) ? lo : hi;
        if (toward < 0 || Double.isInfinite(score(toward))) return Double.NaN;
        return Math.round((b + feeds.get(toward)) / 2 * 1000) / 1000.0;
    }

    // e.g. "0.35: 4.1 % spread | 0.50: 1.2 % | 0.65: 0.9 % | 0.80: two at once"
    public String summary() {
        List<Integer> order = new ArrayList<>();
        for (int i = 0; i < feeds.size(); i++) order.add(i);
        order.sort((a, b) -> Double.compare(feeds.get(a), feeds.get(b)));
        StringBuilder s = new StringBuilder();
        for (int i : order) {
            if (dips.get(i).isEmpty()) continue;
            if (s.length() > 0) s.append(" | ");
            s.append(String.format(Locale.US, "%.2f: ", feeds.get(i)));
            if (doubled.get(i)) s.append("two at once");
            else if (dips.get(i).size() < SHOTS_EACH) s.append(dips.get(i).size()).append(" shot(s)");
            else s.append(String.format(Locale.US, "%.1f %% spread", 100 * score(i)));
        }
        return s.toString();
    }

    // Watches the wheel speed through one shot: how deep it dipped below the speed before, and whether it dipped twice
    // (it fell more than `threshold`, came back at least half way, then, while still feeding, fell again by at least
    // half the first dip).
    public static final class Dip {
        private final double before, threshold;
        private double min, low;
        private boolean in = false;
        private int count = 0;

        public Dip(double before, double threshold) {
            this.before = before;
            this.threshold = threshold;
            min = before;
            low = before;
        }

        // feeding: the intake is still pushing (a second element can only arrive then; later swings are the recovery)
        public void add(double v, boolean feeding) {
            min = Math.min(min, v);
            // a second element dips the wheel about as deep as the first; the recovery's wobble far less
            double needed = count == 0 ? threshold : Math.max(threshold, 0.5 * (before - min));
            if (!in && before - v > needed && (count == 0 || feeding)) {
                in = true;
                count++;
                low = v;
            }
            if (in) {
                low = Math.min(low, v);
                if (v > low + 0.5 * (before - low)) in = false;
            }
        }

        public double depth() {
            return before - min;
        }

        public boolean reachedWheel() {
            return count > 0;
        }

        public boolean twice() {
            return count >= 2;
        }
    }
}
